const employees = [
  { id: 1, name: "A", department: "IT", salary: 80000 },
  { id: 2, name: "B", department: "HR", salary: 50000 },
  { id: 3, name: "C", department: "IT", salary: 100000 },
  { id: 4, name: "D", department: "HR", salary: 70000 },
  { id: 5, name: "E", department: "Finance", salary: 90000 },
  { id: 6, name: "F", department: "IT", salary: 120000 }
];

const highestSalary = (data) => {
  let output = [];

  for (let i = 0; i < data.length; i++) {
    let found = false;

    for (let j = 0; j < output.length; j++) {
      if (data[i].department === output[j].department) {
        output[j].salary += data[i].salary;
        found = true;
        break;
      }
    }

    if (!found) {
      output[output.length] = {
        name: data[i].name,
        department: data[i].department,
        salary: data[i].salary
      };
    }
  }

  return output;
};

console.log('-->', highestSalary(employees));
